const shadowPantherSheet=new Image();shadowPantherSheet.assetSrc='assets/shadow-panther-v1.png';
function beginShadowPanther(e){let angle=Math.atan2(p.y-e.y,p.x-e.x);e.state='attack';e.elapsed=0;e.struck=false;e.facing=Math.cos(angle)-Math.sin(angle)<0?-1:1;e.attack={pattern:'shadowPantherEcho',bespoke:true,windup:1,origin:{x:e.x,y:e.y},last:{x:e.x,y:e.y},angle,first:false,second:false};}
function shadowPantherCone(a,point,range,half){let dx=point.x-a.origin.x,dy=point.y-a.origin.y,d=Math.hypot(dx,dy),angle=Math.atan2(dy,dx)-a.angle;return d<=range+1e-8&&(d<1e-8||Math.abs(Math.atan2(Math.sin(angle),Math.cos(angle)))<=half+1e-10)&&lineClear(a.origin,point);}
function retreatShadowPanther(e,time){let a=e.attack,t=Math.min(1,Math.max(0,(time-1.2)/.5)),target={x:a.origin.x-Math.cos(a.angle)*120*t,y:a.origin.y-Math.sin(a.angle)*120*t};if(!a.retreatBlocked){let start={x:e.x,y:e.y},steps=Math.max(1,Math.ceil(dist(e,target)/6));for(let i=1;i<=steps;i++){let q={x:start.x+(target.x-start.x)*i/steps,y:start.y+(target.y-start.y)*i/steps};if(!passable(q.x,q.y,20)||!lineClear(e,q,20)){a.retreatBlocked=true;break;}e.x=q.x;e.y=q.y;}}a.last={x:e.x,y:e.y};}
const shadowPantherAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r10e5')return shadowPantherAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='shadowPantherEcho'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=170&&clear){beginShadowPanther(e);return;}e.state='idle';if(d>800&&!e.aware)return;if(e.nav<=0){e.nav=.8;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,135*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,18)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.last)>24){e.attack=null;e.state='idle';e.t=1.5;return;}e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;
 if(!a.first&&e.elapsed>=1){a.first=true;e.struck=true;if(shadowPantherCone(a,p,180,Math.PI*5/18))hurt(50);playSound('impact',a.origin.x,a.origin.y);}
 if(e.elapsed>=1.2)retreatShadowPanther(e,e.elapsed);
 if(!dead&&!a.second&&e.elapsed>=2.2){a.second=true;if(shadowPantherCone(a,p,320,Math.PI*7/36))hurt(85);playSound('impact',a.origin.x,a.origin.y);}
 if(e.elapsed>=3.2){e.attack=null;e.state='idle';e.t=2.8;}
};
const shadowPantherDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r10e5'||!shadowPantherSheet.complete||!shadowPantherSheet.naturalWidth||!shadowPantherSheet.naturalHeight)return shadowPantherDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0),a=e.attack;if(e.hp<=0)f={row:2,col:3};else if(a?.pattern==='shadowPantherEcho')f={row:2,col:e.elapsed<.5?0:e.elapsed<1?1:e.elapsed<1.2?2:3};let q=project(e.x,e.y),sw=shadowPantherSheet.naturalWidth/4,sh=shadowPantherSheet.naturalHeight/3,w=270,h=w*sh/sw,anchor=[[.83,.83,.83,.83],[.8,.8,.78,.78],[.81,.82,.83,.81]][f.row][f.col];ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,shadowPantherSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(shadowPantherSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const shadowPantherSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r10e5'?175:shadowPantherSizeBase(e);
function drawShadowPantherCone(a,range,half,color){let q=project(a.origin.x,a.origin.y);ctx.beginPath();ctx.moveTo(q.x,q.y);for(let i=0;i<=20;i++){let angle=a.angle-half+half*2*i/20,v=project(a.origin.x+Math.cos(angle)*range,a.origin.y+Math.sin(angle)*range);ctx.lineTo(v.x,v.y);}ctx.closePath();ctx.strokeStyle=color;ctx.lineWidth=2;ctx.stroke();}
const shadowPantherGroundBase=drawGroundEffects;drawGroundEffects=()=>{shadowPantherGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r10e5'):enemies)){let a=e.attack;if(e.species!=='r10e5'||e.hp<=0||a?.pattern!=='shadowPantherEcho'||!visibleAt(a.origin.x,a.origin.y))continue;ctx.save();if(e.elapsed<1.2)drawShadowPantherCone(a,180,Math.PI*5/18,'#c4b5db');if(e.elapsed>=1&&e.elapsed<2.45){drawShadowPantherCone(a,320,Math.PI*7/36,a.second?'#f4d8ff':'#a578cc');ctx.globalAlpha=a.second?.7:.35;drawRegionEnemy({...e,x:a.origin.x,y:a.origin.y,elapsed:a.second?1.05:.8,flash:0},175);}ctx.restore();}};
if(typeof registerDirectEnemy==='function')registerDirectEnemy('r10e5',animateEnemy,drawRegionEnemy);
